  "player_descriptions": {
    "2": "Tarun, you kept fighting despite the scoreline and had a shot on target and a crucial save for the team. Keep your head up; your defensive clearances were important, showing you didn't give up!",
    "4": "Pillai, you were fantastic today, bagging four goals and two assists. What a performance, you were clinical in front of goal and a menace to the opposition. Keep up the great work!",
    "7": "Alinga, you had a great game, scoring two goals and proving to be a real threat going forward. Your shots were on target and you contributed to a big win for the team. Well done!",
    "5": "Lional, you put in a strong performance with a goal and an assist, plus some great tackles and interceptions. Your efforts in both attack and defense were crucial to the team's success. Keep that work rate up!",
    "6": "Mo, you were working hard out there, creating offensive opportunities for the team. Although your shots didn't find the target this time, your passing was important in the build-up play.",
    "8": "Kalyan, you showed great energy, getting into dangerous positions and creating chances. Even though you didn't score, you kept the pressure on the opposition defense and contributed with some interceptions.",
    "3": "Hareesh, you contributed to the attack and showed some good vision with those key passes. Keep working on getting those shots on target, and you'll be troubling the opposition in no time!",
    "1": "Vinay, you helped create some chances, assisting a goal and making a shot on target. You also contributed defensively, making some important saves. Keep up the good work on both ends of the pitch!",
    "9": "Jaltan, you showed some good attacking intent, getting shots on target and causing problems for the defense. You also helped out defensively, making some interceptions and tackles. Keep pushing forward!",
    "12": "Rohan, a goal is a fantastic contribution! Keep getting into those scoring positions and continue to show that sharpness in front of goal. Your attacking presence made a difference today.",
    "11": "Pitar, you had a busy day in goal, making some important saves. Although the scoreline wasn't in your favor, your efforts prevented it from being even worse.",
    "13": "Kavin, you showed promising signs with an assist and some important tackles and interceptions. Keep developing your game and you'll become an even greater asset to the team."
  },
  "match_description": "Well, what a day at the park for Ballers for Life, dispatching Street Legends with a resounding 8-0 victory! Lional Masi drew first blood early on, setting the stage for a dominant performance. But the star of the show? That would be Pillai, bagging no less than four goals! Alinga Halandh wasn't far behind, contributing a brace of his own as Ballers for Life ran rampant, securing a memorable win.",
